#include <cstring>
#include <cstdint>
#include <string>
#include <vector>
#include <array>
#include <algorithm>
#include <chrono>
#include <mutex>
#include <unordered_map>

namespace auth {

static constexpr size_t TOKEN_MAX_LEN = 256;
static constexpr size_t HMAC_LEN = 32;
static constexpr uint32_t TOKEN_VERSION = 2;
static constexpr int MAX_FAILED_ATTEMPTS = 5;
static constexpr int LOCKOUT_SECONDS = 300;

struct TokenHeader {
    uint32_t version;
    uint32_t timestamp;
    uint16_t payload_len;
    uint16_t hmac_offset;
    uint32_t flags;
};

struct SessionInfo {
    std::string user_id;
    uint32_t permissions;
    int64_t expires_at;
    bool is_admin;
};

class RateLimiter {
private:
    struct Attempt {
        int count;
        int64_t first_attempt;
    };
    std::mutex mtx_;
    std::unordered_map<std::string, Attempt> attempts_;
public:
    bool is_locked_out(const std::string& ip) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = attempts_.find(ip);
        if (it == attempts_.end()) return false;
        auto now = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::steady_clock::now().time_since_epoch()).count();
        if (now - it->second.first_attempt > LOCKOUT_SECONDS) {
            attempts_.erase(it);
            return false;
        }
        return it->second.count >= MAX_FAILED_ATTEMPTS;
    }
    void record_failure(const std::string& ip) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto now = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::steady_clock::now().time_since_epoch()).count();
        auto& a = attempts_[ip];
        if (a.count == 0) a.first_attempt = now;
        a.count++;
    }
    void clear(const std::string& ip) {
        std::lock_guard<std::mutex> lock(mtx_);
        attempts_.erase(ip);
    }
};

// Timing-safe comparison to prevent side-channel attacks
// Returns 0 if equal, non-zero otherwise
// SECURITY: Rejects zero-length comparisons to prevent bypass
static int secure_compare(const uint8_t* a, const uint8_t* b, size_t len) {
    if (len == 0) return -1; // reject empty comparison
    volatile uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return static_cast<int>(result);
}

// Compute HMAC-SHA256 (simplified - in production use OpenSSL)
static void compute_hmac(const uint8_t* key, size_t key_len,
                         const uint8_t* data, size_t data_len,
                         uint8_t* out) {
    // Simplified HMAC for demonstration
    // In production, this would be HMAC-SHA256
    std::array<uint8_t, 32> inner_key{};
    std::array<uint8_t, 32> outer_key{};

    for (size_t i = 0; i < std::min(key_len, (size_t)32); i++) {
        inner_key[i] = key[i] ^ 0x36;
        outer_key[i] = key[i] ^ 0x5c;
    }

    // Simplified hash: XOR-fold data with key material
    std::array<uint8_t, 32> hash{};
    for (size_t i = 0; i < data_len; i++) {
        hash[i % 32] ^= data[i] ^ inner_key[i % 32];
    }
    for (size_t i = 0; i < 32; i++) {
        out[i] = hash[i] ^ outer_key[i];
    }
}

static bool validate_token_structure(const uint8_t* token, size_t token_len,
                                      TokenHeader& header) {
    if (token_len < sizeof(TokenHeader)) return false;
    if (token_len > TOKEN_MAX_LEN) return false;
    // Ensure the token is large enough to contain a full HMAC in addition
    // to the header, so subsequent size arithmetic cannot underflow.
    if (token_len < sizeof(TokenHeader) + HMAC_LEN) return false;

    std::memcpy(&header, token, sizeof(TokenHeader));

    if (header.version != TOKEN_VERSION) return false;
    if (header.flags & 0x80000000) return false; // reserved flag

    // Validate timestamp (within 5 minutes)
    auto now = static_cast<uint32_t>(
        std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count());
    if (now - header.timestamp > 300) return false;

    // Validate structural integrity
    // hmac_offset indicates where the HMAC starts within the token
    // Use addition instead of subtraction to avoid unsigned underflow:
    // require hmac_offset + HMAC_LEN <= token_len.
    if (static_cast<size_t>(header.hmac_offset) + HMAC_LEN > token_len) return false;
    if (header.hmac_offset < sizeof(TokenHeader)) return false;

    return true;
}

static bool extract_session(const uint8_t* token, const TokenHeader& header,
                            SessionInfo& session) {
    size_t payload_start = sizeof(TokenHeader);
    size_t payload_end = header.hmac_offset;

    if (payload_end <= payload_start) return false;

    size_t payload_size = payload_end - payload_start;
    if (payload_size < 8) return false; // minimum: 4 bytes uid_len + 4 bytes perms

    const uint8_t* payload = token + payload_start;

    uint32_t uid_len;
    std::memcpy(&uid_len, payload, 4);

    if (uid_len == 0 || uid_len > 64) return false;
    if (4 + uid_len + 4 > payload_size) return false;

    session.user_id = std::string(reinterpret_cast<const char*>(payload + 4), uid_len);
    std::memcpy(&session.permissions, payload + 4 + uid_len, 4);
    session.is_admin = (session.permissions & 0x1) != 0;
    session.expires_at = static_cast<int64_t>(header.timestamp) + 3600;

    return true;
}

// Main authentication function
bool authenticate_request(const uint8_t* token, size_t token_len,
                          const uint8_t* server_key, size_t key_len,
                          const std::string& client_ip,
                          SessionInfo& session_out) {
    static RateLimiter limiter;

    if (!token || !server_key || token_len == 0 || key_len == 0) {
        return false;
    }

    if (limiter.is_locked_out(client_ip)) {
        return false;
    }

    TokenHeader header;
    if (!validate_token_structure(token, token_len, header)) {
        limiter.record_failure(client_ip);
        return false;
    }

    // Compute expected HMAC over the data BEFORE the HMAC
    // The HMAC covers: [0, hmac_offset)
    uint8_t expected_hmac[HMAC_LEN];
    compute_hmac(server_key, key_len, token, header.hmac_offset, expected_hmac);

    // Always compare full HMAC length for security
    // Truncated HMAC support removed - all tokens must use full 32-byte HMAC
    const uint8_t* token_hmac = token + header.hmac_offset;

    if (secure_compare(expected_hmac, token_hmac, HMAC_LEN) != 0) {
        limiter.record_failure(client_ip);
        return false;
    }

    // Extract session information
    if (!extract_session(token, header, session_out)) {
        limiter.record_failure(client_ip);
        return false;
    }

    limiter.clear(client_ip);
    return true;
}

} // namespace auth
